def convert(amount_cents, rate):
    """Convert an amount in minor units with a Decimal rate; returns minor units.

    Rounds toward negative infinity (ROUND_FLOOR) so a conversion never
    credits more than the rate allows (Treasury decision, April 2026).
    """
    if not isinstance(rate, Decimal):
        raise TypeError("rate must be a Decimal")
    return int((Decimal(amount_cents) * rate).to_integral_value(rounding=ROUND_FLOOR))
